public async Task<LocationSuggestion[]> SearchAsync(string query, string language, CancellationToken ct)
{
    if (query.Any(char.IsControl)) throw new ArgumentException("Invalid location search.");
    query = string.Join(' ', query.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
    if (query.Length is < 3 or > 200 || query.Any(char.IsControl) || language is not ("vi" or "en"))
        throw new ArgumentException("Invalid location search.");
    var config = options.CurrentValue;
    if (!Uri.TryCreate(config.BaseUrl, UriKind.Absolute, out var origin) || origin.Scheme != "https" ||
        origin.Query.Length != 0 || origin.Fragment.Length != 0 || origin.UserInfo.Length != 0 || string.IsNullOrWhiteSpace(config.UserAgent))
        throw new LocationSearchUnavailableException();
    var key = $"{origin}|{language}|{query.ToUpperInvariant()}";
    if (cache.TryGetValue(key, out LocationSuggestion[]? hit)) return hit!;
    // Reject concurrent misses rather than building an unbounded request queue.
    if (!await gate.WaitAsync(0, ct)) throw new LocationSearchBusyException();

