public (string Text, IReadOnlyDictionary<string, string> Tokens) Protect(string text)
{
    // Vietnamese arrives as NFC or NFD depending on the keyboard; compare in one form.
    text = text.Normalize(NormalizationForm.FormC);
    var tokens = new Dictionary<string, string>();

    foreach (var term in _terms.Where(t => text.Contains(t, StringComparison.Ordinal)))
    {
        var token = $"[[T{tokens.Count + 1}]]";
        text = text.Replace(term, token, StringComparison.Ordinal);
        tokens[token] = term;
    }

    return (text, tokens);

