public async Task<SynthesizedSpeech> SynthesizeWithTimingAsync(string text, string lang, string voice, CancellationToken ct = default)
{
    if (timingClient is null) throw new InvalidOperationException("The timepoint TTS client is not configured.");
    var script = TimedSpeechScript.Create(text);
    // SSML counts toward Google's input-byte limit. Preserve existing plain-text synthesis
    // when adding marks would push an otherwise valid narration over that limit.
    var timed = Encoding.UTF8.GetByteCount(script.Ssml) <= 5000;
    var request = new Google.Cloud.TextToSpeech.V1Beta1.SynthesizeSpeechRequest
    {
        Input = timed ? new() { Ssml = script.Ssml } : new() { Text = text },
        Voice = new() { Name = voice, LanguageCode = string.Join('-', voice.Split('-').Take(2)) },
        AudioConfig = new() { AudioEncoding = Google.Cloud.TextToSpeech.V1Beta1.AudioEncoding.Mp3 },
    };
    if (timed) request.EnableTimePointing.Add(Google.Cloud.TextToSpeech.V1Beta1.SynthesizeSpeechRequest.Types.TimepointType.SsmlMark);

