public async Task<int> IngestAsync(UsageBatch batch, CancellationToken ct)
{
    var now = time.GetUtcNow();
    if (batch.Mode != "live" || batch.Events is null || batch.Events.Length is < 1 or > 50)
        throw new ArgumentException("Invalid analytics batch.");
    foreach (var e in batch.Events)
        if (e.EventId == Guid.Empty || (e.Kind != "error" && (e.VisitorId == Guid.Empty || e.TabId == Guid.Empty)) ||
            !Kinds.Contains(e.Kind) || !Languages.Contains(e.Language) ||
            e.OccurredAt < now.AddDays(-1) || e.OccurredAt > now.AddMinutes(5) ||
            (e.Kind is "view" or "play" && (e.PoiId is null || e.ContextId is null || e.ContextId == Guid.Empty)) ||
            (e.Kind == "error" && (e.PoiId is null || !ErrorKinds.Contains(e.ErrorType ?? ""))) ||
            e.PoiId == Guid.Empty || e.Version is < 1 || (e.AudioLanguage != null && !Languages.Contains(e.AudioLanguage)))
