export function recordPlaying(track: { poiId: string; version: number; lang: Lang; url: string }) {
  if (!trackingEnabled()) { lastTrack = ''; countedPlay = false; return }
  const key = `${track.poiId}:${track.version}:${track.lang}:${track.url}`
  if (key !== lastTrack) { lastTrack = key; playbackId = uuid(); countedPlay = false }
  if (countedPlay) return
  countedPlay = true; enqueue('play', track.poiId, { contextId: playbackId, version: track.version, audioLanguage: track.lang })
}
