  const summary: Cell[][] = [[t('Scope'), scope === 'overview' ? t('Overview') : scope === 'places' ? t('All places') : report.name],
    [t('Period'), new Date(report.from), new Date(Math.max(new Date(report.from).getTime(), new Date(report.to).getTime() - 1))], [t('As of'), new Date(report.asOf)], ['UTC+07:00'],
    [t('Customers'), observed ? report.visitors : null], [t('Online at export time'), report.online], [t('Listens'), observed ? report.plays : null]]
  if (scope === 'overview') summary.push([t('Total places'), report.placeCounts.total], [t('Active places'), report.placeCounts.live],
    [t('Hidden places'), report.placeCounts.hidden], [t('Draft places'), report.placeCounts.draft],
    [t('Most viewed place'), mostViewed?.name ?? null], [t('Most listened language'), topLanguage ? language(topLanguage.language).nativeName : null])
  if (scope === 'places') summary.push([t('Viewing now'), report.viewing])
  if (scope === 'places') return [{ name: t('Summary'), rows: summary }, { name: t('Places'), rows: [
    [t('Place'), t('Visitors'), t('Viewing now'), t('Listens')], ...report.places.map(p => [p.name, observed ? p.visitors : null, p.online, observed ? p.plays : null]),
  ] }]

