    UserManager<ApplicationUser> users, TokenIssuer issuer, TimeProvider clock, CancellationToken cancellationToken)
{
    if (!ValidRefresh(request.RefreshToken)) return InvalidRefresh();
    var hash = TokenIssuer.Hash(request.RefreshToken!);
    var token = await db.RefreshTokens.AsNoTracking().Include(t => t.User)
        .SingleOrDefaultAsync(t => t.TokenHash == hash, cancellationToken);
    var now = clock.GetUtcNow();
    if (token is null || token.ExpiresAt <= now || token.ConsumedAt is not null || token.RevokedAt is not null ||
        !token.User.IsActive || await users.IsLockedOutAsync(token.User)) return InvalidRefresh();
    var roles = await ActiveRolesAsync(db, token.UserId, cancellationToken);
    if (roles.Length == 0) return InvalidRefresh();
    var issued = issuer.Create(token.User, roles);
    await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken);

